function group(id,title,source){SEED_TASKS.push({id,title,parent:null,kind:'group',sources:source,status:'Backlog',discipline:'Mixed',owner:'Unassigned',videos:[],description:'',criteria:[],dependencies:[],estimate:0,priority:'Medium',notes:''});}
