group('001','Setup Map and Camera',['map','flow','implementation']);
task('002','001','Setup map for videos 001, 002, 005, 006','Art',MANUAL,'Assemble the full two-level layout with a resource yard and parking on Level 2; crusher, rail, processing, product stack and customer area below. Include the elevator connection.',['Layout follows the first map diagram.','Reserve space for one, two and four rail routes.','Include four customer bays and the player delivery area.'],['map','reuse','implementation'],[],2,'In Progress');
task('003','001','Setup map for videos 003, 004','Art',AUTO,'Assemble the automated-delivery layout. The player remains in the vehicle on Level 2, while customer queues and production occupy Level 1.',['Two middle production routes and two additional routes fit the diagram.','Vehicle-accessible upgrade nodes are on Level 2.','Customer queues remain visible from the planned camera shots.'],['map','flow','implementation'],[],2,'Ready');
task('004','001','Setup short map for videos 007, 008','Art',SHORT,'Assemble the compact map with the wide crusher and direct delivery to four customer bays. This variant does not use a processing machine.',['Layout follows the short-map diagram.','Bays 1–2 start open; reserve unlock positions for 3–4.','Resource yard supports the final junk-car or gold-yard upgrade.'],['map','flow','implementation'],[],1.5);
task('005','001','Frame the main camera across both levels','Dev',ALL_VIDEOS,'Use the Tiles Survive reference for the main view. Clearly communicate the height difference and direction of material movement.',['Both levels are readable in the main view.','Crusher-to-customer route is visually understandable.','Important actions and nodes remain in frame.'],['map','references'],['002'],1,'Review');
task('006','001','Setup player-follow and production camera shots','Dev',MANUAL,'Follow the player between levels and show the material route from crusher through rail to the processing machine.',['Camera follows elevator travel without losing the player.','Production handoffs are clear.','Scripted transitions are short and smooth; player control locks temporarily.'],['implementation','flow'],['002','005'],1.5,'Ready');
task('007','001','Setup automated production and customer shots','Dev',AUTO,'Alternate between the Level 2 player and Level 1 production/customer views. Include an opening queue shot and the final continuous production-to-cash payoff.',['Opening customer queue and angry emojis are readable.','Crushing, processing, delivery and cash each get sufficient screen time.','Return to player view for upgrade interactions.'],['flow','implementation'],['003','005'],1.5);
task('008','001','Design industrial steering-wheel UI','Art',['005','006'],'Create the realistic, industrial steering-wheel control asset shown by the Simulator references.',['Control appearance follows the brief references.','The wheel can rotate independently in the UI.','Asset is ready for the drag-input implementation.'],['new'],[],1,'Done');
task('009','001','Implement Simulator camera and steering controls','Dev',['005','006'],'Use Simulator camera and drag steering only during the collection sequence, then return to the main view.',['Drag input steers similarly to a joystick.','Wheel rotation follows steering input.','Camera and UI switch off after collection.'],['new','implementation','flow'],['005','008'],1.5);
group('010','Prepare Reused and New Assets',['reuse','new','references']);
task('011','010','Audit and prepare player and vehicle assets','Art',ALL_VIDEOS,'Locate the player from existing Playables/Creative Pyramid, vacuum vehicle from the Korean creative, and bulldozer from Coin Pusher.',['Source locations are recorded.','Vehicle attachment and upgrade variations are available.','Assets match the realistic industrial direction.'],['reuse','references'],[],1,'Ready');
task('012','010','Prepare crusher, rail, elevator and node assets','Art',ALL_VIDEOS,'Reuse crusher blades from the Korean creative, rail and nodes from Creative Pyramid, and reference the Playable 002 elevator.',['Crusher intake aligns with Level 2.','Output can connect to the lower production route.','Reusable parts are ready for scene integration.'],['reuse'],[],1,'Done');
task('013','010','Prepare rusty materials and customer vehicles','Art',ALL_VIDEOS,'Prepare irregular scrap, rusty metal cubes and lightly rusted industrial customer vehicles.',['Scrap retains irregular shapes.','Coin Pusher cubes receive rusty-metal textures.','Playable 006 customer vehicles fit the industrial style.'],['reuse','references'],[],1.5,'In Progress');
task('014','010','Create processing press and product assets','Art',['001','002','003','004','005','006'],'Create the automatic press, flat metal plates for Scrap Yard and gears for Ore.',['Press supports a readable processing animation.','Metal plates and gears are visually distinct.','No processing machine is needed for short-map videos.'],['new'],[],2,'Ready');
task('015','010','Create junk-car yard upgrade','Art',['007'],'Create rows of different old vehicles for the final scrap-yard upgrade.',['Several junk-car types are arranged in even rows.','Appearance remains realistic and industrial.'],['new','flow'],[],1.5);
task('016','010','Prepare gold-yard upgrade assets','Art',['008'],'Reuse the gold yard from the Vietnamese Coin Pusher creative.',['Asset source is recorded.','Final upgrade visibly changes the rusty-metal yard to gold.'],['reuse','flow'],[],0.5);
group('017','Implement Collection and Player Flow',['implementation','flow','keys']);
task('018','017','Implement vacuum collection, stacking and dumping','Dev',SCRAP,'Vacuum scrap onto the vehicle and dump the entire stack into the crusher using a cheat key at Parking.',['Trash stacks on the vehicle.','Dump occurs only after the cheat action.','Vehicle capacity and cluster quantities are tunable per video.'],['implementation','flow','keys'],['011','013'],2,'In Progress');
task('019','017','Implement grinding and bulldozer attachment swap','Dev',ORE,'Grind rusty metal cubes, switch to the bulldozer head using a cheat key, then push materials into the crusher.',['Attachment switch is visually clear.','Ore is pushed rather than vacuumed.','The correct controls are enabled for Ore variants.'],['implementation','flow','keys'],['011','013'],2);
task('020','017','Implement entering, exiting and elevator travel','Dev',MANUAL,'Allow the player to leave the vehicle, travel between floors and return to driving.',['Cheat action supports leaving the vehicle.','Player can use the elevator in both directions.','Always-in-vehicle variants disable the exit flow.'],['implementation','flow'],['011','012'],1.5);
task('021','017','Implement handheld product stack and delivery','Dev',MANUAL,'The on-foot player collects finished products and carries them to customer vehicles.',['Player stack capacity is tunable.','Products unstack into the customer delivery area.','Delivery supports metal plates and gears.'],['implementation','flow'],['014','020'],1.5);
task('022','017','Configure collection capacity and respawn by video','Dev',ALL_VIDEOS,'Keep materials non-respawning for 003–004 with an initial one-cluster capacity; respawn collected clusters for 007–008.',['003–004 allow collecting all remaining material after upgrade.','007–008 respawn collected clusters.','Unspecified respawn behavior for other videos is flagged for confirmation.'],['implementation','flow'],['018','019'],1);
group('023','Build Production and Overload Systems',['implementation','new']);
task('024','023','Implement crusher input and metal-block output','Dev',ALL_VIDEOS,'The crusher activates automatically when material arrives; synchronize crushing actions with output generation.',['Accepts dumped scrap and pushed ore.','Metal blocks appear in sync with crushing.','Output connects to the route selected for the video.'],['implementation','reuse'],['012','018','019'],2,'Ready');
task('025','023','Implement rail transport and processing handoffs','Dev',['001','002','003','004','005','006'],'Transport metal blocks from the crusher to the press using the selected rail configuration.',['Manual variants support 1 → 2 → 4 routes.','Automated variants support two middle routes plus two new routes.','Material movement remains visually readable.'],['implementation'],['012','024'],2);
task('026','023','Implement automatic press production','Dev',['001','002','003','004','005','006'],'Process incoming metal into flat plates for Scrap Yard or gears for Ore.',['Press operates on material arrival.','Animation timing matches product creation.','Output type follows the video selection.'],['implementation','new'],['014','025'],1.5);
task('027','023','Implement short-map direct delivery','Dev',SHORT,'Send crusher metal blocks directly to customer bays, bypassing the press.',['No processing step appears.','Delivery reaches only unlocked bays.','Four-bay flow works after the unlock.'],['implementation','flow'],['004','024'],1.5);
task('028','023','Create rail overload and final product collapse','Dev',MANUAL,'Show a material bottleneck at the rail before upgrades and a finished-product pile that topples at the ending.',['Overload thresholds are tunable.','Rail upgrade visibly clears the bottleneck.','Collisions and collapse do not hide important nodes or the player.'],['implementation','flow'],['025','026'],2);
group('029','Implement Customers and Payments',['implementation','flow']);
task('030','029','Implement customer loads and one-time payment','Dev',ALL_VIDEOS,'Each customer pays only after receiving the required load. Sale price, quantity and upgrade costs are tunable.',['Each order credits money once.','VFX presentation cannot duplicate payment.','A full load triggers the correct per-video selling flow.'],['implementation'],['013'],1.5,'Ready');
task('031','029','Implement manual delivery and cash attraction','Dev',MANUAL,'Player carries products to customers; cash automatically moves to the player after the load is complete.',['Bays 1–2 accept deliveries.','Bays 3–4 stay locked through the ending.','Cash follows completion of the full customer order.'],['implementation','flow'],['021','030'],1);
task('032','029','Implement automated sales and vehicle-to-cash payoff','Dev',AUTO,'Auto-deliver products. Provide a toggle between a vehicle turning into cash and a vehicle leaving with cash-gain UI.',['Both payment presentation options work.','Final payoff uses vehicle-to-cash.','Queue progression and cash UI remain readable.'],['implementation','flow'],['026','030'],1.5);
task('033','029','Implement short-map sales and customer replacement','Dev',SHORT,'Full customer vehicles transfer money to the player vehicle and leave; new vehicles enter unlocked bays.',['Money targets the player vehicle.','Only open bays accept replacement vehicles.','The flow supports four active bays after unlock.'],['implementation','flow'],['027','030'],1);
group('034','Setup Upgrades and Video Variants',['implementation','flow']);
task('035','034','Implement visible vehicle upgrades','Dev',ALL_VIDEOS,'Vehicle upgrades increase capacity and collection efficiency and visibly change the model or attachment.',['Capacity and efficiency are tunable.','Upgrade appearance is easy to read.','Collection capacity follows each video flow.'],['implementation'],['011','018','019'],1.5);
task('036','034','Configure rail upgrades and locked bays','Dev',MANUAL,'Start with one route, upgrade to two then four, and retain locked bays 3–4 through the ending.',['Both rail upgrades activate in order.','Final unlock nodes light up without opening bays 3–4.','Node positions support the on-foot flow.'],['implementation','flow'],['025','030'],1);
task('037','034','Configure automated rail and bay expansion','Dev',AUTO,'Start with the two middle routes; a Level 2 upgrade opens the other two routes and customer bays.',['Vehicle can activate the Level 2 node.','New routes and bays become visibly available.','Camera can show the expansion.'],['implementation','flow'],['025','032'],1);
task('038','034','Configure short-map bay and yard upgrades','Dev',SHORT,'Open bays 3–4 through an unlock, then expose the final junk-car or gold-yard upgrade.',['Upgrade nodes detect the player vehicle.','007 upgrades to a junk-car yard.','008 upgrades to a gold yard.'],['implementation','flow'],['015','016','033'],1);
task('039','034','Configure eight selectable video starts','Dev',ALL_VIDEOS,'Provide per-video configuration for layout, collection, product, capacity, camera, selling and upgrades. Follow the project rule: one scene with selectable starts.',['All eight video starts are selectable.','005 and 006 reuse their base flow with Simulator collection.','Variant settings avoid duplicating shared systems.'],['flow','implementation'],['022','027','031','032','033','035','036','037','038'],2);
